CREATE OR REPLACE FUNCTION public.submit_appointment(_name text,_phone text,_email text,_date date,_time text,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN INSERT INTO public.appointment_rate_limits(key) VALUES(_phone) ON CONFLICT(key) DO UPDATE SET last_submission=now() WHERE appointment_rate_limits.last_submission < now()-interval '60 seconds'; IF NOT FOUND THEN RAISE EXCEPTION 'Please wait a minute before submitting another request.'; END IF; INSERT INTO public.appointments(patient_name,phone,email,preferred_date,preferred_time,reason) VALUES(_name,_phone,_email,_date,_time,_reason) RETURNING id INTO new_id; RETURN new_id; END $$;
CREATE FUNCTION public.submit_appointment_request(_name text,_phone text,_email text,_date text,_time text,_reason text) RETURNS uuid LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.submit_appointment(_name,_phone,_email,NULLIF(_date,'')::date,_time,_reason) $$;
REVOKE ALL ON FUNCTION public.submit_appointment_request(text,text,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_appointment_request(text,text,text,text,text,text) TO service_role;